INSERT INTO `configurations` (`configuration_id`,`bundle_id`,`config_type`,`config_key`,`description`,`config_value`,`target`,`isPreLoginConfiguration`) VALUES ('NUO_SFDC_55','NUO_SFDC_CONFIG_BUNDLE','PREFERENCE','MOBILEPHONENUMBERCONSENT_CONFIG','MobilePhoneNumberConsent','{\"UserActionName\": \"MobilePhoneNumberConsent\",\"Group\": \"Legal\",\"Skippable\": \"false\",\"Title\": \"Mobile phone number consent\",\"UserActionType\": \"Radio-ButtonSelection\",\"Options\": [\"The bank can call or text me through automated means\",\"The bank can only contact me through non-automated means\",\"The bank can\'t contact me (this may impact your approval)\"],\"OptionsType\": \"PREDEFINED\",\"Description\": \"If the phone number provided on this application is a mobile phone number, it is my mobile phone number, and by clicking on the button below, I consent to receive auto-dialed and prerecorded/artificial calls, including texts, relating to my relationship with this bank. It may include handling, servicing, and billing for any of my account(s). Message and data rates may apply. You can stop these messages by contacting our service center.\",\"ObjectAttribute\": \"\",\"ObjectName\": \"\",\"NeedsReview\": \"true\"}','CLIENT','1');
